//! Compares our links with links generated by eMule (see tests/fixtures/README.md).

use std::path::PathBuf;
use std::sync::atomic::AtomicBool;

use ed2k_vault_core::hasher::Hasher;
use ed2k_vault_core::link::{self, LinkOptions};

#[derive(Debug, PartialEq, Eq)]
struct Fields {
    name: String,
    size: String,
    hash: String,
    aich: Option<String>,
    hashset: Option<String>,
}

fn percent_decode(text: &str) -> String {
    let bytes = text.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            let hex = std::str::from_utf8(&bytes[i + 1..i + 3]).unwrap_or("");
            if let Ok(byte) = u8::from_str_radix(hex, 16) {
                out.push(byte);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn parse(link: &str) -> Fields {
    let parts: Vec<&str> = link.trim().split('|').collect();
    assert!(
        parts.len() >= 5 && parts[1] == "file",
        "not a file link: {link}"
    );
    let mut fields = Fields {
        name: percent_decode(parts[2]),
        size: parts[3].to_string(),
        hash: parts[4].to_lowercase(),
        aich: None,
        hashset: None,
    };
    for extra in &parts[5..] {
        if let Some(root) = extra.strip_prefix("h=") {
            fields.aich = Some(root.to_uppercase());
        } else if let Some(set) = extra.strip_prefix("p=") {
            fields.hashset = Some(set.to_lowercase());
        }
    }
    fields
}

fn fixtures_dir() -> PathBuf {
    std::env::var_os("ED2K_VAULT_FIXTURES")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures"))
}

#[test]
fn links_match_the_ones_generated_by_emule() {
    let dir = fixtures_dir();
    let hasher = Hasher::new(4, true).unwrap();
    let mut checked = 0;
    for entry in std::fs::read_dir(&dir).unwrap().flatten() {
        let expected_path = entry.path();
        if expected_path.extension().and_then(|e| e.to_str()) != Some("expected") {
            continue;
        }
        let data_path = expected_path.with_extension("");
        let name = data_path
            .file_name()
            .unwrap()
            .to_string_lossy()
            .into_owned();
        let expected = std::fs::read_to_string(&expected_path).unwrap();
        let digest = hasher
            .hash_file(&data_path, &AtomicBool::new(false), &|_| {})
            .unwrap();
        let ours = link::build(
            &name,
            &digest,
            LinkOptions {
                hashset: true,
                aich: true,
            },
        );
        assert_eq!(parse(&ours), parse(&expected), "mismatch for {name}");
        checked += 1;
    }
    eprintln!("{checked} fixture(s) compared with eMule");
}
